// Client-side port of light.days.Days.currentDays and light.days.DayRecord.ageStr:
// builds the day-record rows entirely from a JSON payload embedded by the Twirl
// template, so a statically-exported page keeps rotating "today's" anniversaries
// and showing the correct age without needing to be regenerated by the server.
(function() {

  function parseDate(s) {
    var parts = s.split("-").map(Number);
    return new Date(parts[0], parts[1] - 1, parts[2]);
  }

  function dayOfYear(date) {
    var start = new Date(date.getFullYear(), 0, 1);
    return Math.floor((date - start) / 86400000) + 1;
  }

  function isSameDate(a, b) {
    return a.getFullYear() === b.getFullYear() &&
      a.getMonth() === b.getMonth() &&
      a.getDate() === b.getDate();
  }

  // Port of DaysHelper.years: Russian pluralization for "N лет/года/год"
  function yearsLabel(y) {
    var mod100 = y % 100, mod10 = y % 10;
    if (mod100 >= 10 && mod100 <= 20) return y + " лет";
    if (mod10 === 1) return y + " год";
    if (mod10 >= 2 && mod10 <= 4) return y + " года";
    return y + " лет";
  }

  // Port of DayRecord.ageStr: prefer the first date's year, else the record's yearOpt
  function ageStr(record) {
    var eventYear = record.dates.length ? parseDate(record.dates[0]).getFullYear() : record.year;
    if (eventYear === null || eventYear === undefined) return "";
    return yearsLabel(new Date().getFullYear() - eventYear);
  }

  function buildRow(template, record) {
    var row = template.content.cloneNode(true);

    var link = row.querySelector(".day-title a");
    link.href = record.href;
    link.textContent = record.title;

    var desc = row.querySelector(".day-desc");
    desc.textContent = record.desc ? " (" + record.desc + ")" : "";

    var age = ageStr(record);
    var ageWrap = row.querySelector(".age-wrap");
    if (age) {
      row.querySelector(".age-str").textContent = age;
    } else if (ageWrap) {
      ageWrap.remove();
    }

    var today = record.dates.some(function(d) { return isSameDate(parseDate(d), new Date()); });
    if (today) row.querySelector(".day-title").classList.add("strong");

    return row;
  }

  // Port of Days.currentDays: sort ascending by day-of-year, then rotate the list so
  // it starts right after the most recent past anniversary (or wraps to the last
  // entry of the year if none has passed yet)
  function rotateToToday(records) {
    var dated = records.filter(function(r) { return r.dates.length > 0; });
    if (!dated.length) return dated;

    var todayDoy = dayOfYear(new Date());
    var sorted = dated.slice().sort(function(a, b) {
      var doyA = dayOfYear(parseDate(a.dates[0])), doyB = dayOfYear(parseDate(b.dates[0]));
      if (doyA !== doyB) return doyA - doyB;
      return parseDate(a.dates[0]).getFullYear() - parseDate(b.dates[0]).getFullYear();
    });

    var pastCount = sorted.filter(function(r) {
      return dayOfYear(parseDate(r.dates[0])) < todayDoy;
    }).length;

    var rotateAt = pastCount > 0 ? pastCount - 1 : sorted.length - 1;
    return sorted.slice(rotateAt).concat(sorted.slice(0, rotateAt));
  }

  function render(container) {
    var script = container.querySelector("[data-days-records]");
    var list = container.querySelector("[data-days-list]");
    var template = container.querySelector("[data-days-row-template]");
    if (!script || !list || !template) return;

    var records = JSON.parse(script.textContent);
    var mode = container.getAttribute("data-days-container");
    var ordered = mode === "rotate" ? rotateToToday(records) : records;

    ordered.forEach(function(record) {
      list.appendChild(buildRow(template, record));
    });
  }

  function init() {
    var containers = document.querySelectorAll("[data-days-container]");
    for (var i = 0; i < containers.length; i++) render(containers[i]);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }

}).call(this);
